// Plain-code check of the follow-up text before it is sent. Blocked follow-ups are not sent and are written to the Log tab.
const body = String($input.item.json.output?.body || '');
const reasons = [];
if (!body.trim()) reasons.push('Body is empty');
const words = body.trim().split(/\s+/).length;
if (words > 160) reasons.push('Too long (' + words + ' words)');
const banned = ['garanti', 'guaranteed', '%100', '100%', 'ücretsiz', 'free trial', 'son şans', 'last chance'];
const hits = banned.filter(b => body.toLowerCase().includes(b));
if (hits.length) reasons.push('Hype wording: ' + hits.join(', '));
for (const r of sensitiveIssues(body)) reasons.push(r);

return { json: {
  ...$input.item.json,
  fu_check_status: reasons.length ? 'Blocked' : 'OK',
  fu_check_notes: reasons.join('; '),
} };

// Trade-secret rule (Nil's compliance plan): no buyer names, order volumes, prices, capacities or margins in outreach text.
function sensitiveIssues(text) {
  const t = String(text || '');
  const low = t.toLowerCase();
  const issues = [];
  const buyers = ['zara', 'inditex', 'h&m', 'hennes', 'primark', 'c&a', 'mango', 'marks & spencer', 'm&s', 'tesco', 'lidl', 'aldi', 'decathlon', 'hugo boss', 'adidas', 'puma', 'nike', 'esprit', 's.oliver', 'tom tailor', 'bestseller', 'zalando', 'about you', 'otto', 'benetton', 'diesel', "levi's", 'levis', 'kiabi', 'celio', 'promod', 'etam', 'carrefour', 'auchan', 'tchibo', 'takko', 'ernsting', 'peek & cloppenburg', 'hunkemöller', 'we fashion', 'jack & jones', 'vero moda', 'pepe jeans', 'desigual', 'el corte ingl', 'cortefiel', 'mayoral', 'g-star', 'scotch & soda', 'zeeman', 'matalan', 'river island', 'new look', 'boohoo', 'asos', 'sinsay', 'cropp', 'mohito', 'pull&bear', 'pull & bear', 'bershka', 'stradivarius', 'massimo dutti', 'oysho', 'ikea', 'jysk', 'armani', 'gucci', 'prada', 'burberry', 'ralph lauren', 'tommy hilfiger', 'calvin klein', 'uniqlo', 'lacoste', 'superdry', 'jd sports', 'intersport', 'engelbert strauss', 'koton', 'defacto', 'lc waikiki'];
  // Whole-word match only: "zara" must not fire inside "yazarak", nor "otto" inside "cotton".
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const wordHit = (name) => new RegExp('(^|[^a-z0-9çğıöşüâîû])' + esc(name) + '(?=$|[^a-z0-9çğıöşüâîû])').test(low);
  const named = buyers.filter(wordHit);
  if (named.length) issues.push('Names a buyer or brand: ' + named.join(', '));
  if (/(€|£|₺|\$|\b(eur|usd|gbp|tl)\b)/i.test(t)) issues.push('Mentions money or prices');
  if (/\b\d[\d.,]*\s*(adet|parça|ton|tons|tonnes|kg|metre|meters|pcs|pieces|units|orders|order|sipariş)\b/i.test(t)) issues.push('Mentions order volumes or quantities');
  const words = ['sipariş hacmi', 'sipariş adedi', 'order volume', 'order quantity', 'minimum order', 'moq', 'fiyat', 'price', 'birim fiyat', 'tedarikçisi', 'supplier of', 'supplies to', 'supplier to', 'müşteriniz', 'your customer', 'your client', 'your buyer', 'alıcınız', 'customer list', 'müşteri listesi', 'kapasite', 'capacity', 'marj', 'margin', 'ciro', 'revenue', 'turnover'];
  const hits = words.filter(w => low.includes(w));
  if (hits.length) issues.push('Commercially sensitive wording: ' + hits.join(', '));
  return issues;
}

// Builds an RFC 2822 reply that Gmail keeps in the original thread (threadId + Re: subject + In-Reply-To/References).
// The text sent is the draft Nil approved in the Leads column "Follow-up Draft".
const meta = $input.item.json;
const headers = (meta.payload && meta.payload.headers) || [];
const msgId = (headers.find(h => String(h.name).toLowerCase() === 'message-id') || {}).value || '';
const thread = $('Get Thread').first().json;
const original = (thread.messages || [])[0] || {};
const to = original.To || $('Loop Over Follow-ups').item.json.Email;
let subject = String(original.Subject || $('Loop Over Follow-ups').item.json.Subject || '');
if (!/^re:/i.test(subject)) subject = 'Re: ' + subject;
const body = String($('Loop Over Follow-ups').item.json['Follow-up Draft'] || '');
if (!body.trim()) throw new Error('Follow-up Draft is empty for ' + $('Loop Over Follow-ups').item.json['Lead ID']);
const encSubject = '=?UTF-8?B?' + Buffer.from(subject, 'utf8').toString('base64') + '?=';
const lines = [
  'To: ' + to,
  'Subject: ' + encSubject,
  msgId ? 'In-Reply-To: ' + msgId : null,
  msgId ? 'References: ' + msgId : null,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
  '',
  Buffer.from(body, 'utf8').toString('base64'),
].filter(l => l !== null);
const raw = Buffer.from(lines.join('\r\n'), 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return { json: { raw, threadId: thread.id || $('Loop Over Follow-ups').item.json['Gmail Thread ID'], to, subject, in_reply_to: msgId } };

// Runs once when the follow-up loop is finished. Counts what happened this run.
const count = (name) => { try { return $(name).all().length; } catch (e) { return 0; } };
const ids = (name) => { try { return $(name).all().map(i => i.json['Lead ID'] || '').filter(Boolean); } catch (e) { return []; } };
let sent = [];
try { sent = $('Update Follow-up Row').all().map(i => (i.json['Lead ID'] || '') + ' (' + (i.json.Stage || 'follow-up') + ')'); } catch (e) {}
const drafted = ids('Save Follow-up Draft');
return [{ json: {
  sent_count: sent.length,
  sent_list: sent.join(', '),
  drafted_count: drafted.length,
  drafted_list: drafted.join(', '),
  blocked_count: count('Log Follow-up Blocked'),
  declined_count: count('Log Follow-up Declined'),
} }];

// Approval gate for follow-ups. Looks at the lead row (not the Gmail thread).
const lead = $('Loop Over Follow-ups').item.json;
const draft = String(lead['Follow-up Draft'] || '').trim();
const approved = String(lead.Approved || '').trim();
let action = 'draft';
if (draft) {
  if (approved === 'Yes') action = 'send';
  else if (approved === 'No') action = 'decline';
  else if (approved === 'Edit') action = 'draft';
  else action = 'wait';
}
return { json: {
  lead_id: lead['Lead ID'],
  fu_action: action,
  fu_previous_draft: draft,
  fu_edit_notes: approved === 'Edit' ? String(lead['Nil Notes'] || '').trim() : '',
} };
